import { useEffect, useMemo, useRef, useState, type FormEvent } from 'react'
import { io, type Socket } from 'socket.io-client'
import {
  ArrowRight, ArrowUpRight, Bell, CalendarDays, Check, CheckCheck,
  ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, LayoutDashboard,
  LogOut, Menu, MessageCircle, MoreHorizontal, Plus, Search, Send, Settings2, Shield, SlidersHorizontal,
  Sparkles, Users, X,
} from 'lucide-react'

type Page = 'Overview' | 'Appointments' | 'Messages' | 'Office hours' | 'Faculty directory' | 'Administration'
type Role = 'landing' | 'student' | 'faculty'
type Appointment = { id: string; date: Date; time: string; type: string; status: 'Confirmed' | 'Pending' | 'Rejected'; mode: string; studentName?: string; studentId?: string; section?: string }
type ChatMessage = { id: string; from: 'student' | 'faculty'; text: string; time: string }
type Contact = { id: string; name: string; role: string; initials: string; color: string; unread?: number; online?: boolean; last: string; messages: ChatMessage[] }
type Professor = { name: string; email: string; id: string; phone: string }

const navItems: { label: Page; icon: typeof LayoutDashboard; badge?: string }[] = [
  { label: 'Overview', icon: LayoutDashboard }, { label: 'Appointments', icon: CalendarDays, badge: '2' },
  { label: 'Messages', icon: MessageCircle, badge: '3' }, { label: 'Office hours', icon: Clock3 },
  { label: 'Faculty directory', icon: Users },
]
const facultyNavItems: { label: Page; icon: typeof LayoutDashboard; badge?: string }[] = [
  { label: 'Overview', icon: LayoutDashboard }, { label: 'Appointments', icon: CalendarDays, badge: '2' },
  { label: 'Messages', icon: MessageCircle, badge: '3' }, { label: 'Office hours', icon: Clock3 },
  { label: 'Administration', icon: Shield },
]
const initialAppointments: Appointment[] = [
  { id: 'APT-1042', date: new Date(2026, 10, 24), time: '10:30 AM', type: 'Thesis consultation', status: 'Confirmed', mode: 'In person', studentName: 'Alex Rivera', studentId: '2023-00418-MN-0', section: 'BPA 3-2' },
  { id: 'APT-1047', date: new Date(2026, 10, 26), time: '2:00 PM', type: 'Course advising', status: 'Pending', mode: 'Video call', studentName: 'Jamie Flores', studentId: '2024-00971-MN-0', section: 'BPA 2-1' },
]
const contactSeed: Contact[] = [
  { id: '1', name: 'Dr. Maria L. Santos', role: 'Program Chair · Public Administration', initials: 'MS', color: 'rose', unread: 1, online: true, last: '10:42 AM', messages: [
    { id: 'm1', from: 'faculty', text: 'Good morning! How can I help with your policy analysis paper?', time: '10:28 AM' },
    { id: 'm2', from: 'student', text: 'Good morning, Ma’am. I wanted to ask about the scope for our final paper.', time: '10:35 AM' },
    { id: 'm3', from: 'faculty', text: 'Of course. Let’s focus on local governance. You can bring your outline to our consultation on Thursday.', time: '10:42 AM' },
  ] },
  { id: '2', name: 'Prof. Daniel Reyes', role: 'Faculty · Political Science', initials: 'DR', color: 'sand', last: 'Yesterday', messages: [
    { id: 'm4', from: 'student', text: 'Thank you, Sir. I’ll send the updated outline before class.', time: 'Yesterday' },
    { id: 'm5', from: 'faculty', text: 'Sounds good. I’ll review it when it arrives.', time: 'Yesterday' },
  ] },
  { id: '3', name: 'Prof. Alyssa Cruz', role: 'Faculty · Public Administration', initials: 'AC', color: 'blue', unread: 2, last: 'Monday', messages: [
    { id: 'm6', from: 'faculty', text: 'Your request for advising is received. Please book a slot here.', time: 'Monday' },
  ] },
]
const facultyContactSeed: Contact[] = [
  { id: '201', name: 'Jamie Flores', role: 'BPA 2-1 · Student', initials: 'JF', color: 'blue', unread: 1, last: '9:18 AM', messages: [
    { id: 'fs1', from: 'student', text: 'Good morning, Ma’am. I sent a request to discuss my course plan.', time: '9:12 AM' },
    { id: 'fs2', from: 'faculty', text: 'Thanks, Jamie. I’ll take a look before we meet.', time: '9:18 AM' },
  ] },
  { id: '202', name: 'Alex Rivera', role: 'BPA 3-2 · Student', initials: 'AR', color: 'gold', last: 'Yesterday', messages: [
    { id: 'fs3', from: 'student', text: 'I’ve attached the outline for my policy analysis paper.', time: 'Yesterday' },
  ] },
]
const dates = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
const officeDays = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const formatDate = (date: Date, options: Intl.DateTimeFormatOptions) => new Intl.DateTimeFormat('en-PH', options).format(date)
const isBookableDay = (day: number, cellIndex: number, month: Date) => {
  const date = new Date(month.getFullYear(), month.getMonth(), day)
  return date >= new Date(2026, 10, 23) && cellIndex % 7 !== 6
}
const formatHour = (time: string) => {
  const [hour, minute] = time.split(':').map(Number)
  return formatDate(new Date(2026, 0, 1, hour, minute), { hour: 'numeric', minute: '2-digit' })
}

function LandingPage({ onStudent, onFaculty }: { onStudent: () => void; onFaculty: () => void }) {
  return <main className="landing-shell"><header className="landing-nav"><a className="brand" href="#home"><span className="brand-seal"><img src="/pup-seal.png" alt="PUP seal" /></span><span className="brand-copy"><strong>CPSPA<span> CONNECT</span></strong><small>POLYTECHNIC UNIVERSITY OF THE PHILIPPINES</small></span></a><span className="landing-nav-note"><span className="live-dot" /> A simpler way to reach your department</span><button className="landing-faculty-link" onClick={onFaculty}>Faculty access <ArrowRight size={15} /></button></header><section className="landing-hero"><div className="landing-copy"><span className="eyebrow"><span className="landing-star">✳</span> COLLEGE OF POLITICAL SCIENCE AND PUBLIC ADMINISTRATION</span><h1>Your next conversation<br />starts <em>here.</em></h1><p>Book a consultation, ask a question, or get in touch with CPSPA faculty—all in one place built around your time.</p><div className="landing-actions"><button className="primary-button" onClick={onStudent}><CalendarDays size={17} /> Book an appointment <ArrowRight size={16} /></button><button className="landing-secondary" onClick={onFaculty}><Users size={17} /> Login as faculty</button></div><div className="landing-assurance"><Shield size={15} /><span>No student account needed</span><i /> <span>Mon–Sat · 7 AM–5 PM</span></div></div><div className="landing-art"><div className="landing-halo halo-one"/><div className="landing-halo halo-two"/><div className="landing-seal"><img src="/pup-seal.png" alt="Official seal of the Polytechnic University of the Philippines" /></div><div className="landing-note note-top"><span className="note-icon"><Clock3 size={16}/></span><span><b>Office hours</b><small>Monday to Saturday</small></span></div><div className="landing-note note-bottom"><span className="note-icon note-gold"><MessageCircle size={16}/></span><span><b>Talk directly</b><small>Reach your professors</small></span></div><span className="art-index">01 / YOUR CPSPA</span></div></section><section className="landing-footer"><div><span className="footer-rule"/><span>PUBLIC SERVICE BEGINS WITH A CONVERSATION</span></div><span>Polytechnic University of the Philippines <i>·</i> Manila</span></section></main>
}

function Avatar({ initials, color = 'rose', small = false }: { initials: string; color?: string; small?: boolean }) {
  return <span className={`avatar ${color} ${small ? 'avatar-small' : ''}`}>{initials}</span>
}
function Modal({ title, eyebrow, onClose, children }: { title: string; eyebrow?: string; onClose: () => void; children: React.ReactNode }) {
  return <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><section className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-top"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div><button className="icon-button" onClick={onClose} aria-label="Close"><X size={18} /></button></div>{children}</section></div>
}

export default function App() {
  const [role, setRole] = useState<Role>('landing')
  const [page, setPage] = useState<Page>('Overview')
  const [appointments, setAppointments] = useState(initialAppointments)
  const [contacts, setContacts] = useState(contactSeed)
  const [activeContact, setActiveContact] = useState('1')
  const [bookOpen, setBookOpen] = useState(false)
  const [profOpen, setProfOpen] = useState(false)
  const [rescheduleId, setRescheduleId] = useState('')
  const [rescheduleDate, setRescheduleDate] = useState('2026-11-27')
  const [rescheduleTime, setRescheduleTime] = useState('11:00 AM')
  const [toast, setToast] = useState('')
  const [search, setSearch] = useState('')
  const [chatDraft, setChatDraft] = useState('')
  const [calendarMonth, setCalendarMonth] = useState(new Date(2026, 10, 1))
  const [selectedDate, setSelectedDate] = useState(new Date(2026, 10, 24))
  const [selectedSlot, setSelectedSlot] = useState('10:00 AM')
  const [mobileNav, setMobileNav] = useState(false)
  const [customHours, setCustomHours] = useState(false)
  const [officeSchedule, setOfficeSchedule] = useState(() => officeDays.map((day) => ({ day, start: '07:00', end: '17:00' })))
  const [bookForm, setBookForm] = useState({ name: 'Alex Rivera', studentId: '2023-00418-MN-0', year: '3rd year', section: 'BPA 3-2', topic: '', email: 'alex.rivera@iskolarngbayan.pup.edu.ph', notes: '' })
  const [profForm, setProfForm] = useState({ name: '', email: '', id: '', phone: '' })
  const [professors, setProfessors] = useState<Professor[]>([
    { name: 'Dr. Maria L. Santos', email: 'maria.santos@pup.edu.ph', id: 'PUP-2018', phone: '+63 917 555 0124' },
    { name: 'Prof. Daniel Reyes', email: 'daniel.reyes@pup.edu.ph', id: 'PUP-2291', phone: '+63 917 555 0165' },
    { name: 'Prof. Alyssa Cruz', email: 'alyssa.cruz@pup.edu.ph', id: 'PUP-2408', phone: '+63 917 555 0196' },
  ])
  const socketUrl = import.meta.env.VITE_SOCKET_URL as string | undefined
  const [socketState, setSocketState] = useState<'demo' | 'connected' | 'offline'>('demo')
  const socketRef = useRef<Socket | null>(null)

  useEffect(() => {
    if (!socketUrl) return
    const token = sessionStorage.getItem('cpspa-session-token')
    if (!token) { setSocketState('demo'); return }
    const socket: Socket = io(socketUrl, { transports: ['websocket'], auth: (cb) => cb({ token: sessionStorage.getItem('cpspa-session-token') }) })
    socketRef.current = socket
    const onConnect = () => setSocketState('connected')
    const onDisconnect = () => setSocketState('offline')
    const onNewMessage = (message: { sender_id: number; message: string; sent_at: string }) => {
      setContacts((items) => items.map((contact, index) => index === 0 ? { ...contact, last: formatDate(new Date(message.sent_at), { hour: 'numeric', minute: '2-digit' }), messages: [...contact.messages, { id: `live-${Date.now()}`, from: message.sender_id === 100 ? 'student' : 'faculty', text: message.message, time: formatDate(new Date(message.sent_at), { hour: 'numeric', minute: '2-digit' }) }] } : contact))
    }
    socket.on('connect', onConnect); socket.on('disconnect', onDisconnect); socket.on('new_message', onNewMessage)
    return () => { socket.off('connect', onConnect); socket.off('disconnect', onDisconnect); socket.off('new_message', onNewMessage); socket.disconnect(); socketRef.current = null }
  }, [socketUrl])

  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 3500); return () => window.clearTimeout(timer) }, [toast])
  const active = contacts.find((c) => c.id === activeContact) ?? contacts[0]
  const filteredContacts = contacts.filter((c) => `${c.name} ${c.role}`.toLowerCase().includes(search.toLowerCase()))
  const currentNavItems = role === 'faculty' ? facultyNavItems : navItems
  const calendarCells = useMemo(() => {
    const first = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), 1)
    const start = (first.getDay() + 6) % 7
    const count = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + 1, 0).getDate()
    return [...Array(start).fill(0), ...Array.from({ length: count }, (_, i) => i + 1)]
  }, [calendarMonth])

  const showPage = (next: Page) => { setPage(next); setMobileNav(false) }
  const enterStudent = () => { setRole('student'); setContacts(contactSeed); setActiveContact('1'); setPage('Overview'); setBookOpen(true) }
  const enterFaculty = () => { setRole('faculty'); setContacts(facultyContactSeed); setActiveContact('201'); setPage('Overview'); setBookOpen(false) }
  const returnToLanding = () => { setRole('landing'); setPage('Overview'); setBookOpen(false); setMobileNav(false) }
  const sendMessage = (e: FormEvent) => {
    e.preventDefault()
    const text = chatDraft.trim()
    if (!text) return
    const now = new Date()
    const localMessage: ChatMessage = { id: `local-${Date.now()}`, from: role === 'faculty' ? 'faculty' : 'student', text, time: formatDate(now, { hour: 'numeric', minute: '2-digit' }) }
    setContacts((items) => items.map((c) => c.id === activeContact ? { ...c, last: localMessage.time, messages: [...c.messages, localMessage] } : c))
    if (socketState === 'connected') {
      socketRef.current?.emit('send_message', { receiver_id: Number(activeContact) + 10, message: text }, (response: { success: boolean; message?: string }) => {
        if (!response.success) setToast(response.message ?? 'The message could not be delivered.')
      })
    } else {
      window.setTimeout(() => setContacts((items) => items.map((c) => c.id === activeContact ? { ...c, messages: [...c.messages, { id: `reply-${Date.now()}`, from: role === 'faculty' ? 'student' : 'faculty', text: role === 'faculty' ? 'Thank you, Ma’am. I’ll be there.' : 'Thanks for your message. I’ve received this and will get back to you soon.', time: formatDate(new Date(), { hour: 'numeric', minute: '2-digit' }) }] } : c)), 900)
    }
    setChatDraft('')
  }
  const bookAppointment = (e: FormEvent) => {
    e.preventDefault()
    if (selectedDate < new Date(2026, 10, 23) || selectedDate.getDay() === 0) { setToast('Choose an available weekday or Saturday for your appointment.'); return }
    if (!bookForm.topic.trim()) { setToast('Add a reason for your appointment to continue.'); return }
    setAppointments((items) => [...items, { id: `APT-${1050 + items.length}`, date: selectedDate, time: selectedSlot, type: bookForm.topic, status: 'Pending', mode: 'In person', studentName: bookForm.name, studentId: bookForm.studentId, section: `${bookForm.year} · ${bookForm.section}` }])
    setBookOpen(false); setBookForm((f) => ({ ...f, topic: '', notes: '' })); setToast(`Appointment request sent for ${formatDate(selectedDate, { month: 'short', day: 'numeric' })} at ${selectedSlot}.`)
  }
  const addProfessor = (e: FormEvent) => {
    e.preventDefault()
    if (!profForm.name.trim() || !profForm.email.trim() || !profForm.id.trim() || !profForm.phone.trim()) return
    setProfessors((items) => [...items, profForm]); setProfOpen(false); setToast(`${profForm.name} was added to the CPSPA faculty directory.`); setProfForm({ name: '', email: '', id: '', phone: '' })
  }
  const updateAppointmentStatus = (id: string, status: Appointment['status']) => {
    setAppointments((items) => items.map((appointment) => appointment.id === id ? { ...appointment, status } : appointment))
    setToast(status === 'Confirmed' ? 'Appointment confirmed. The student can now see the update.' : 'Appointment declined. The student can now see the update.')
  }
  const saveReschedule = (e: FormEvent) => {
    e.preventDefault()
    const date = new Date(`${rescheduleDate}T12:00:00`)
    if (date.getDay() === 0 || date < new Date(2026, 10, 23)) { setToast('Choose a future Monday–Saturday date.'); return }
    setAppointments((items) => items.map((appointment) => appointment.id === rescheduleId ? { ...appointment, date, time: rescheduleTime, status: 'Pending' } : appointment))
    setRescheduleId(''); setToast('Reschedule request sent to the student for confirmation.')
  }
  const changeMonth = (n: number) => setCalendarMonth(new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + n, 1))

  if (role === 'landing') return <LandingPage onStudent={enterStudent} onFaculty={enterFaculty} />

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}>
      <a className="brand" href="#home" onClick={(e) => { e.preventDefault(); returnToLanding() }}><span className="brand-seal"><img src="/pup-seal.png" alt="PUP seal" /></span><span className="brand-copy"><strong>CPSPA<span> CONNECT</span></strong><small>POLYTECHNIC UNIVERSITY OF THE PHILIPPINES</small></span></a>
      <div className="side-label">{role === 'faculty' ? 'FACULTY PORTAL' : 'STUDENT PORTAL'}</div>
      <nav className="navigation">{currentNavItems.filter((item) => item.label !== 'Administration').map(({ label, icon: Icon, badge }) => <button key={label} className={`nav-item ${page === label ? 'active' : ''}`} onClick={() => showPage(label)}><Icon size={18} strokeWidth={1.8} /><span>{label}</span>{badge && <span className="nav-badge">{badge}</span>}</button>)}</nav>
      {role === 'faculty' && <><div className="side-label admin-label">MANAGEMENT</div><nav className="navigation"><button className={`nav-item ${page === 'Administration' ? 'active' : ''}`} onClick={() => showPage('Administration')}><Shield size={18} strokeWidth={1.8} /><span>Administration</span><span className="admin-pill">Admin</span></button></nav></>}
      <div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><CircleHelp size={17} /></div><strong>{role === 'faculty' ? 'Faculty workspace' : 'Need a hand?'}</strong><p>{role === 'faculty' ? 'Manage your consultations and student messages.' : 'Find answers about booking and office hours.'}</p><button onClick={() => setToast(role === 'faculty' ? 'You are in the faculty demo workspace.' : 'Help center: Contact the CPSPA office at local 284.')}>{role === 'faculty' ? 'Demo mode active' : 'Visit help center'} <ArrowUpRight size={13} /></button></div><button className="profile-button" onClick={returnToLanding}><Avatar initials={role === 'faculty' ? 'MS' : 'AR'} color={role === 'faculty' ? 'rose' : 'gold'} /><span><strong>{role === 'faculty' ? 'Dr. Maria Santos' : 'Alex Rivera'}</strong><small>{role === 'faculty' ? 'Faculty · Program Chair' : 'Student · BPA 3-2'}</small></span><LogOut size={16} /></button></div>
    </aside>

    <main className={`main-area ${page === 'Messages' ? 'main-messages-area' : ''}`}>
      <header className="topbar"><button className="icon-button menu-button" onClick={() => setMobileNav((v) => !v)} aria-label="Open navigation"><Menu size={20} /></button><div className="breadcrumb"><span>CPSPA Connect</span><ChevronRight size={15} /><strong>{page}</strong></div><div className="top-actions"><div className="portal-status"><span className={`status-dot ${socketState === 'connected' ? 'live' : ''}`} />{role === 'faculty' ? 'Faculty demo' : socketState === 'connected' ? 'Live connection' : socketState === 'offline' ? 'Reconnecting' : 'Student demo'}</div><button className="icon-button notification-button" aria-label="Notifications" onClick={() => setToast('You’re all caught up on notifications.')}><Bell size={18} /><i /></button><button className="top-avatar" onClick={returnToLanding}>{role === 'faculty' ? 'MS' : 'AR'}</button></div></header>
      <div className={`content-wrap ${page === 'Messages' ? 'messages-content-wrap' : ''}`}>
        {page === 'Overview' && role === 'student' && <>
          <section className="welcome-row"><div><div className="eyebrow welcome-eyebrow">MONDAY, NOVEMBER 23, 2026 <span>·</span> MANILA, PH</div><h1>A better way to<br className="mobile-break" /> connect, <em>Alex.</em></h1><p className="welcome-subtitle">Your CPSPA office, one step closer. Book a consultation or reach your faculty directly.</p></div><button className="primary-button book-primary" onClick={() => setBookOpen(true)}><Plus size={17} /> Book an appointment <ArrowRight size={15} /></button></section>
          <section className="overview-grid">
            <div className="overview-main">
              <div className="stats-row"><article className="stat-card"><div className="stat-icon stat-maroon"><CalendarDays size={17} /></div><span className="stat-caption">UPCOMING APPOINTMENTS</span><div className="stat-number">{appointments.length.toString().padStart(2, '0')}<span className="stat-note"><span className="live-dot" /> This semester</span></div></article><article className="stat-card"><div className="stat-icon stat-gold"><MessageCircle size={17} /></div><span className="stat-caption">UNREAD MESSAGES</span><div className="stat-number">03<span className="stat-note">From your faculty</span></div></article><article className="stat-card"><div className="stat-icon stat-olive"><Clock3 size={17} /></div><span className="stat-caption">OFFICE AVAILABILITY</span><div className="stat-number stat-open">Open<span className="stat-note">Until 5:00 PM today</span></div></article></div>
              <section className="panel schedule-panel"><div className="section-heading"><div><span className="eyebrow">YOUR SCHEDULE</span><h2>Next up</h2></div><button className="text-link" onClick={() => showPage('Appointments')}>All appointments <ArrowRight size={14} /></button></div>{appointments.length ? <div className="appointment-list">{appointments.slice(0, 3).map((apt) => <div className="appointment-row" key={apt.id}><div className="date-tile"><b>{formatDate(apt.date, { day: '2-digit' })}</b><span>{formatDate(apt.date, { month: 'short' }).toUpperCase()}</span></div><div className="appointment-info"><strong>{apt.type}</strong><span><Clock3 size={13} /> {apt.time} <i>·</i> {apt.mode}</span></div><span className={`tag ${apt.status === 'Confirmed' ? 'tag-confirmed' : apt.status === 'Rejected' ? 'tag-rejected' : 'tag-pending'}`}><span />{apt.status}</span><button className="more-button" aria-label="Appointment options" onClick={() => setToast(`Appointment ${apt.id} · ${apt.type}`)}><MoreHorizontal size={19} /></button></div>)}</div> : <div className="empty-state">No appointments yet. Choose a time that works for you.</div>}</section>
              <section className="panel message-preview"><div className="section-heading"><div><span className="eyebrow">PICK UP WHERE YOU LEFT OFF</span><h2>Recent conversations</h2></div><button className="text-link" onClick={() => showPage('Messages')}>View messages <ArrowRight size={14} /></button></div><div className="conversation-row" onClick={() => { setActiveContact('1'); showPage('Messages') }}><Avatar initials="MS" color="rose" /><div className="conversation-copy"><strong>Dr. Maria L. Santos <span className="online-mini" /> </strong><p>Of course. Let’s focus on local governance. You can bring your outline to our consultation on Thursday.</p></div><span className="conversation-time">10:42 AM</span><span className="unread-mark" /></div><div className="conversation-row" onClick={() => { setActiveContact('2'); showPage('Messages') }}><Avatar initials="DR" color="sand" /><div className="conversation-copy"><strong>Prof. Daniel Reyes</strong><p>Sounds good. I’ll review it when it arrives.</p></div><span className="conversation-time">Yesterday</span></div></section>
            </div>
            <aside className="overview-side"><section className="panel mini-calendar"><div className="calendar-head"><div><span className="eyebrow">YOUR CALENDAR</span><h2>{formatDate(calendarMonth, { month: 'long', year: 'numeric' })}</h2></div><div className="calendar-arrows"><button onClick={() => changeMonth(-1)} aria-label="Previous month"><ChevronLeft size={16} /></button><button onClick={() => changeMonth(1)} aria-label="Next month"><ChevronRight size={16} /></button></div></div><div className="calendar-days">{dates.map((day) => <span key={day}>{day[0]}</span>)}</div><div className="calendar-grid">{calendarCells.map((day, i) => { const current = day && day === selectedDate.getDate() && calendarMonth.getMonth() === selectedDate.getMonth(); const hasAppt = appointments.some((a) => day === a.date.getDate() && calendarMonth.getMonth() === a.date.getMonth()); return day ? <button key={`${day}-${i}`} className={`${current ? 'selected' : ''} ${hasAppt ? 'has-event' : ''}`} onClick={() => setSelectedDate(new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), day))}>{day}{hasAppt && <i />}</button> : <span key={`blank-${i}`} /> })}</div><div className="calendar-legend"><span><i className="legend-dot" /> Appointment</span><button onClick={() => setBookOpen(true)}>Find a time <ArrowRight size={13} /></button></div></section>
              <section className="office-card"><div className="office-topline"><span className="office-sun">✳</span><span>THE CPSPA OFFICE</span><span className="office-live"><i /> OPEN</span></div><h2>Room 303,<br />South Wing.</h2><p>Faculty consultations are available Monday to Saturday, 7:00 AM–5:00 PM.</p><button onClick={() => showPage('Office hours')}>See office hours <ArrowUpRight size={14} /></button><span className="office-ornament">C</span></section>
              <section className="tip-card"><span className="tip-icon"><Sparkles size={15} /></span><div><strong>A quick tip</strong><p>Include a short topic with your request so your professor can prepare ahead.</p></div></section>
            </aside>
          </section>
        </>}

        {page === 'Overview' && role === 'faculty' && <section className="faculty-dashboard page-section"><div className="welcome-row faculty-welcome"><div><div className="eyebrow welcome-eyebrow">MONDAY, NOVEMBER 23, 2026 <span>·</span> FACULTY WORKSPACE</div><h1>Good morning, <em>Ma’am Maria.</em></h1><p className="welcome-subtitle">Here’s what needs your attention today.</p></div><button className="primary-button" onClick={() => showPage('Appointments')}><CalendarDays size={16} /> Manage appointments <ArrowRight size={15} /></button></div><div className="stats-row faculty-stats"><article className="stat-card"><div className="stat-icon stat-maroon"><CalendarDays size={17} /></div><span className="stat-caption">PENDING REQUESTS</span><div className="stat-number">{appointments.filter((appointment) => appointment.status === 'Pending').length.toString().padStart(2, '0')}<span className="stat-note">Awaiting your response</span></div></article><article className="stat-card"><div className="stat-icon stat-gold"><Users size={17} /></div><span className="stat-caption">TODAY’S CONSULTATIONS</span><div className="stat-number">02<span className="stat-note">Next one at 10:30 AM</span></div></article><article className="stat-card"><div className="stat-icon stat-olive"><MessageCircle size={17} /></div><span className="stat-caption">STUDENT MESSAGES</span><div className="stat-number">03<span className="stat-note">Across your inbox</span></div></article></div><section className="panel faculty-requests"><div className="section-heading"><div><span className="eyebrow">REVIEW AND RESPOND</span><h2>Appointment requests</h2></div><button className="text-link" onClick={() => showPage('Appointments')}>View all <ArrowRight size={14} /></button></div>{appointments.filter((appointment) => appointment.status === 'Pending').length ? appointments.filter((appointment) => appointment.status === 'Pending').map((appointment) => <article className="faculty-request-row" key={appointment.id}><div className="date-tile"><b>{formatDate(appointment.date, { day: '2-digit' })}</b><span>{formatDate(appointment.date, { month: 'short' }).toUpperCase()}</span></div><Avatar initials={(appointment.studentName ?? 'ST').split(' ').map((part) => part[0]).slice(0, 2).join('')} color="blue" small /><div className="faculty-request-info"><strong>{appointment.studentName ?? 'CPSPA Student'} <span>{appointment.section}</span></strong><span>{appointment.type} · {formatDate(appointment.date, { weekday: 'short', month: 'short', day: 'numeric' })}, {appointment.time}</span></div><button className="request-reschedule" onClick={() => { setRescheduleId(appointment.id); setRescheduleDate(appointment.date.toISOString().slice(0, 10)) }}>Reschedule</button><button className="request-reject" onClick={() => updateAppointmentStatus(appointment.id, 'Rejected')}>Decline</button><button className="request-accept" onClick={() => updateAppointmentStatus(appointment.id, 'Confirmed')}><Check size={14} /> Accept</button></article>) : <div className="empty-state">All appointment requests have been reviewed.</div>}</section><div className="faculty-overview-bottom"><section className="panel faculty-quick"><span className="eyebrow">YOUR OFFICE</span><h2>Room 303 · South Wing</h2><p>Office hours today: {formatHour(officeSchedule[0].start)}–{formatHour(officeSchedule[0].end)}</p><button className="text-link" onClick={() => showPage('Office hours')}>Edit availability <ArrowRight size={14} /></button></section><section className="panel faculty-quick"><span className="eyebrow">STUDENT INBOX</span><h2>Keep the conversation going.</h2><p>Reply to student questions and coordinate consultations directly.</p><button className="text-link" onClick={() => showPage('Messages')}>Open messages <ArrowRight size={14} /></button></section></div></section>}

        {page === 'Appointments' && <section className="page-section"><div className="page-title-row"><div><span className="eyebrow">{role === 'faculty' ? 'STUDENT CONSULTATIONS' : 'YOUR CPSPA VISITS'}</span><h1>Appointments</h1><p className="page-intro">{role === 'faculty' ? 'Review requests and keep your consultation schedule up to date.' : 'Keep track of your consultations and requests.'}</p></div>{role === 'student' && <button className="primary-button" onClick={() => setBookOpen(true)}><Plus size={17} /> New appointment</button>}</div><div className="panel appointment-page-panel"><div className="filter-row"><div><span className="list-count">{appointments.length} appointments</span><span className="muted"> · Academic year 2026–2027</span></div><button className="filter-button" onClick={() => setToast('Showing appointments for the current semester.')}><SlidersHorizontal size={15} /> This semester <ChevronDown size={14} /></button></div>{appointments.map((apt) => <article className="appointment-full-row" key={apt.id}><div className="date-tile large"><b>{formatDate(apt.date, { day: '2-digit' })}</b><span>{formatDate(apt.date, { month: 'short' }).toUpperCase()}</span></div>{role === 'faculty' && <Avatar initials={(apt.studentName ?? 'ST').split(' ').map((part) => part[0]).slice(0, 2).join('')} color="blue" small />}<div className="appointment-info"><strong>{role === 'faculty' ? apt.studentName ?? 'CPSPA Student' : apt.type}</strong><span>{role === 'faculty' ? apt.type : ''}{role === 'faculty' && <i> · </i>}<Clock3 size={14} /> {formatDate(apt.date, { weekday: 'long' })}, {apt.time} <i>·</i> {apt.mode}</span><small>{role === 'faculty' ? `${apt.studentId ?? 'Student ID on request'} · ${apt.section ?? ''}` : 'Dr. Maria L. Santos · Program Chair'}</small></div><span className={`tag ${apt.status === 'Confirmed' ? 'tag-confirmed' : apt.status === 'Rejected' ? 'tag-rejected' : 'tag-pending'}`}><span />{apt.status}</span>{role === 'faculty' ? <div className="appointment-actions">{apt.status === 'Pending' && <><button className="request-accept" onClick={() => updateAppointmentStatus(apt.id, 'Confirmed')}>Accept</button><button className="request-reject" onClick={() => updateAppointmentStatus(apt.id, 'Rejected')}>Decline</button></>}<button className="request-reschedule" onClick={() => { setRescheduleId(apt.id); setRescheduleDate(apt.date.toISOString().slice(0, 10)); setRescheduleTime(apt.time) }}>Reschedule</button></div> : <button className="row-action" onClick={() => setToast(`Appointment ${apt.id} · ${apt.status}`)}>View details <ArrowRight size={14} /></button>}</article>)}{role === 'student' && <div className="appointment-note"><Shield size={16} /><span>Need to change your plans? Message your professor at least 24 hours before your appointment.</span><button onClick={() => showPage('Messages')}>Message faculty <ArrowRight size={13} /></button></div>}</div></section>}

        {page === 'Messages' && <section className="page-section messages-page"><div className="page-title-row compact-title"><div><span className="eyebrow">{role === 'faculty' ? 'STUDENT INBOX' : 'FACULTY DIRECT LINE'}</span><h1>Messages <span className="title-count">03</span></h1></div><button className="outline-button" onClick={() => role === 'faculty' ? setToast('Select a student conversation from your inbox to reply.') : showPage('Faculty directory')}><Plus size={16} /> New message</button></div><section className="panel chat-panel"><aside className="chat-sidebar"><div className="chat-search"><Search size={15} /><input placeholder="Search conversations" value={search} onChange={(e) => setSearch(e.target.value)} /></div><div className="chat-filter"><span>ALL MESSAGES <b>{contacts.length}</b></span><button aria-label="Conversation settings" onClick={() => setToast('Conversation settings opened.')}><Settings2 size={15} /></button></div>{filteredContacts.map((contact) => <button className={`contact-row ${activeContact === contact.id ? 'contact-active' : ''}`} key={contact.id} onClick={() => setActiveContact(contact.id)}><span className="contact-avatar-wrap"><Avatar initials={contact.initials} color={contact.color} /><i className={contact.online ? 'contact-online' : ''} /></span><span className="contact-main"><span className="contact-name">{contact.name}</span><span className="contact-role">{contact.role}</span><span className="contact-last">{contact.messages[contact.messages.length - 1]?.text}</span></span><span className="contact-trailing"><span>{contact.last}</span>{contact.unread && <b>{contact.unread}</b>}</span></button>)}{role === 'student' && <button className="directory-cta" onClick={() => showPage('Faculty directory')}><span><Plus size={15} /></span> Start a conversation</button>}</aside><section className="chat-conversation"><header className="chat-header"><Avatar initials={active.initials} color={active.color} /><div><strong>{active.name}</strong><span>{active.online ? <><i className="online-mini" /> Online now</> : active.role}</span></div><button className="icon-button chat-more" onClick={() => setToast(`Conversation with ${active.name}`)}><MoreHorizontal size={20} /></button></header><div className="privacy-note"><Shield size={13} /> Messages are private between you and this {role === 'faculty' ? 'student' : 'faculty member'}.</div><div className="messages-thread"><div className="day-divider"><span />TODAY<span /></div>{active.messages.map((message) => <div key={message.id} className={`message-line ${message.from === role ? 'message-out' : ''}`}>{message.from !== role && <Avatar initials={active.initials} color={active.color} small />}<div className="message-content"><div className="bubble">{message.text}</div><span>{message.time}{message.from === role && <CheckCheck size={13} />}</span></div></div>)}</div><form className="chat-compose" onSubmit={sendMessage}><button type="button" className="compose-add" aria-label="Add attachment" onClick={() => setToast('Attachments are not enabled in this demo.')}><Plus size={18} /></button><input value={chatDraft} onChange={(e) => setChatDraft(e.target.value)} placeholder={`Message ${active.name.split(' ')[0]}…`} /><button className="send-button" type="submit" disabled={!chatDraft.trim()} aria-label="Send message"><Send size={16} /></button></form><div className="chat-disclaimer">Please allow 1–2 working days for a response.</div></section></section></section>}

        {page === 'Office hours' && <section className="page-section"><div className="page-title-row"><div><span className="eyebrow">PLAN AHEAD</span><h1>Office hours</h1><p className="page-intro">{role === 'faculty' ? 'Set the days and times students can request a consultation.' : 'See when the CPSPA office is available for student consultations.'}</p></div>{role === 'faculty' && <button className="outline-button" onClick={() => setCustomHours((v) => !v)}><Settings2 size={16} /> {customHours ? 'Done editing' : 'Customize hours'}</button>}</div><div className="office-hours-layout"><section className="panel hours-panel"><div className="section-heading"><div><span className="eyebrow">WEEKLY AVAILABILITY</span><h2>Consultation schedule</h2></div><span className="tag tag-confirmed"><span />Accepting visits</span></div>{officeDays.map((day, index) => <div className={`hours-row ${index === 5 ? 'hours-last' : ''}`} key={day}><div className="day-name"><i className={index === 0 ? 'today-indicator' : ''} />{day}{index === 0 && <span className="today-pill">TODAY</span>}</div>{customHours ? <div className="hours-edit"><input type="time" value={officeSchedule[index].start} onChange={(e) => setOfficeSchedule((items) => items.map((hours, i) => i === index ? { ...hours, start: e.target.value } : hours))} aria-label={`${day} start time`} /><span>to</span><input type="time" value={officeSchedule[index].end} onChange={(e) => setOfficeSchedule((items) => items.map((hours, i) => i === index ? { ...hours, end: e.target.value } : hours))} aria-label={`${day} end time`} /><button onClick={() => setToast(`${day} availability saved.`)}><Check size={14} /></button></div> : <span className="hours-time">{formatHour(officeSchedule[index].start)} <i>—</i> {formatHour(officeSchedule[index].end)}</span>}<span className="hours-status"><i />Available</span></div>)}<div className="hours-footnote"><Clock3 size={15} /> Times shown in Philippine Standard Time (UTC+8)</div></section><aside className="office-side-card"><div className="office-art"><div className="orbit orbit-a"/><div className="orbit orbit-b"/><div className="orbit orbit-c"/><img className="office-art-seal" src="/pup-seal.png" alt="PUP seal" /><span className="art-caption">CPSPA · PUP MANILA</span></div><span className="eyebrow">IN-PERSON CONSULTATIONS</span><h2>Drop by Room 303.</h2><p>South Wing, PUP Main Building. Bring your student ID and any materials you’d like to discuss.</p><button className="text-link" onClick={() => setToast('Office location: Room 303, South Wing, PUP Main Building.')}>Office location <ArrowUpRight size={14} /></button></aside></div><section className="availability-callout"><span><Sparkles size={16} /></span><div><strong>Looking for a specific time?</strong><p>Choose an open slot and we’ll send your professor a request.</p></div>{role === 'faculty' ? <button onClick={() => setCustomHours(true)}>Customize availability <ArrowRight size={14} /></button> : <button onClick={() => setBookOpen(true)}>Browse appointments <ArrowRight size={14} /></button>}</section></section>}

        {page === 'Faculty directory' && <section className="page-section"><div className="page-title-row"><div><span className="eyebrow">YOUR CPSPA FACULTY</span><h1>Faculty directory</h1><p className="page-intro">Find the right person and start a conversation.</p></div><div className="directory-search"><Search size={16} /><input placeholder="Search faculty" value={search} onChange={(e) => setSearch(e.target.value)} /></div></div><div className="faculty-grid">{[
          { name: 'Dr. Maria L. Santos', area: 'Public Administration · Program Chair', initials: 'MS', color: 'rose', hours: 'Consultations available today' },
          { name: 'Prof. Daniel Reyes', area: 'Political Science · Faculty', initials: 'DR', color: 'sand', hours: 'Next available Wednesday' },
          { name: 'Prof. Alyssa Cruz', area: 'Public Administration · Faculty', initials: 'AC', color: 'blue', hours: 'Next available Thursday' },
          { name: 'Dr. Rafael Mendoza', area: 'Public Policy · Faculty', initials: 'RM', color: 'green', hours: 'Next available Friday' },
        ].filter((f) => f.name.toLowerCase().includes(search.toLowerCase())).map((faculty) => <article className="faculty-card" key={faculty.name}><div className="faculty-card-top"><Avatar initials={faculty.initials} color={faculty.color} /><button className="icon-button" onClick={() => setToast(`More about ${faculty.name}`)} aria-label="Faculty information"><MoreHorizontal size={18} /></button></div><h2>{faculty.name}</h2><p>{faculty.area}</p><div className="faculty-availability"><span className="live-dot" />{faculty.hours}</div><div className="faculty-actions"><button className="primary-button" onClick={() => { setActiveContact(faculty.initials === 'MS' ? '1' : faculty.initials === 'DR' ? '2' : '3'); showPage('Messages') }}><MessageCircle size={15} /> Message</button><button className="outline-button" onClick={() => { setBookOpen(true); setToast(`Choose a time to meet with ${faculty.name}.`) }}><CalendarDays size={15} /> Book</button></div></article>)}{professors.slice(3).filter((professor) => professor.name.toLowerCase().includes(search.toLowerCase())).map((professor) => <article className="faculty-card" key={professor.id}><div className="faculty-card-top"><Avatar initials={professor.name.split(' ').map((part) => part[0]).slice(0, 2).join('')} color="green" /><span className="tag tag-pending"><span />Invited</span></div><h2>{professor.name}</h2><p>{professor.email}</p><div className="faculty-availability">Invitation sent · {professor.phone}</div><div className="faculty-actions"><button className="primary-button" onClick={() => setToast('This professor is setting up their account before messages are enabled.')}><MessageCircle size={15} /> Message</button><button className="outline-button" onClick={() => setToast('Appointment booking opens when the professor activates their account.')}><CalendarDays size={15} /> Book</button></div></article>)}</div><div className="faculty-footer"><Shield size={15} /> Faculty responses usually arrive within 1–2 working days.</div></section>}

        {page === 'Administration' && <section className="page-section"><div className="page-title-row"><div><span className="eyebrow">CPSPA PORTAL CONTROLS</span><h1>Administration</h1><p className="page-intro">Manage faculty access and keep the directory current.</p></div><span className="admin-access"><Shield size={15} /> SUPER ADMIN</span></div><div className="admin-stats"><div className="panel admin-stat"><span className="stat-caption">FACULTY MEMBERS</span><strong>24</strong><span>Across CPSPA programs</span></div><div className="panel admin-stat"><span className="stat-caption">ACTIVE THIS TERM</span><strong>21</strong><span><i className="live-dot" /> Available for booking</span></div><div className="panel admin-stat"><span className="stat-caption">PENDING INVITATIONS</span><strong>02</strong><span>Awaiting account setup</span></div></div><section className="panel directory-table"><div className="section-heading"><div><span className="eyebrow">ACCESS MANAGEMENT</span><h2>Faculty accounts</h2></div><button className="primary-button" onClick={() => setProfOpen(true)}><Plus size={16} /> Add professor</button></div>{['Dr. Maria L. Santos', 'Prof. Daniel Reyes', 'Prof. Alyssa Cruz'].map((name, index) => <div className="faculty-table-row" key={name}><Avatar initials={['MS', 'DR', 'AC'][index]} color={['rose', 'sand', 'blue'][index]} small /><div><strong>{name}</strong><span>{['maria.santos@pup.edu.ph', 'daniel.reyes@pup.edu.ph', 'alyssa.cruz@pup.edu.ph'][index]}</span></div><span className="admin-id">PUP-{[2018, 2291, 2408][index]}</span><span className="tag tag-confirmed"><span />Active</span><button className="more-button" onClick={() => setToast(`Faculty account options for ${name}`)}><MoreHorizontal size={19} /></button></div>)}{professors.slice(3).map((professor) => <div className="faculty-table-row" key={professor.id}><Avatar initials={professor.name.split(' ').map((part) => part[0]).slice(0, 2).join('')} color="green" small /><div><strong>{professor.name}</strong><span>{professor.email}</span></div><span className="admin-id">{professor.id}</span><span className="tag tag-pending"><span />Invited</span><button className="more-button" onClick={() => setToast(`${professor.name} · ${professor.phone}`)}><MoreHorizontal size={19} /></button></div>)}<div className="admin-footnote"><Shield size={14} /> Only super administrators can invite or remove faculty accounts.</div></section></section>}
      </div>
      <footer className="page-footer"><span>© 2026 CPSPA · Polytechnic University of the Philippines</span><span><img className="footer-logo" src="/pup-seal.png" alt="PUP seal" /> Iskolar ng Bayan</span></footer>
    </main>

    {bookOpen && <Modal title="Book an appointment" eyebrow="LET’S FIND A TIME" onClose={() => setBookOpen(false)}><form className="booking-form" onSubmit={bookAppointment}><div className="booking-professor"><Avatar initials="MS" color="rose" /><div><strong>Dr. Maria L. Santos</strong><span>Program Chair · Public Administration</span></div><button type="button" className="text-link" onClick={() => { setBookOpen(false); showPage('Faculty directory') }}>Change</button></div><div className="form-label-row"><label>Choose a date</label><span>Appointments available Mon–Sat</span></div><div className="date-picker"><div className="date-picker-head"><button type="button" onClick={() => changeMonth(-1)}><ChevronLeft size={16} /></button><strong>{formatDate(calendarMonth, { month: 'long', year: 'numeric' })}</strong><button type="button" onClick={() => changeMonth(1)}><ChevronRight size={16} /></button></div><div className="picker-days">{['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((x, i) => <span key={`${x}-${i}`}>{x}</span>)}</div><div className="picker-grid">{calendarCells.map((day, i) => day ? <button type="button" disabled={!isBookableDay(day, i, calendarMonth)} className={`${selectedDate.getDate() === day && selectedDate.getMonth() === calendarMonth.getMonth() ? 'picked' : ''} ${[4, 11, 18, 25].includes(day) ? 'slot-full' : ''}`} key={`${day}-${i}`} onClick={() => setSelectedDate(new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), day))}>{day}</button> : <span key={`sp-${i}`} />)}</div></div><div className="form-label-row slot-label"><label>Available times</label><span><i className="legend-dot" /> Open</span></div><div className="slot-grid">{['7:00 AM', '8:00 AM', '9:00 AM', '10:00 AM', '11:00 AM', '12:00 PM', '1:00 PM', '2:00 PM', '3:00 PM', '4:00 PM'].map((slot) => <button key={slot} type="button" disabled={slot === '2:00 PM' && selectedDate.getDate() === 25} className={selectedSlot === slot ? 'slot-selected' : ''} onClick={() => setSelectedSlot(slot)}>{slot}</button>)}</div><div className="form-grid"><label>Student name<input required value={bookForm.name} onChange={(e) => setBookForm({ ...bookForm, name: e.target.value })} /></label><label>Student ID<input required value={bookForm.studentId} onChange={(e) => setBookForm({ ...bookForm, studentId: e.target.value })} /></label><label>Year level<input required value={bookForm.year} onChange={(e) => setBookForm({ ...bookForm, year: e.target.value })} /></label><label>Section<input required value={bookForm.section} onChange={(e) => setBookForm({ ...bookForm, section: e.target.value })} /></label><label>Email <span className="optional">optional</span><input type="email" value={bookForm.email} onChange={(e) => setBookForm({ ...bookForm, email: e.target.value })} /></label><label className="field-wide">What would you like to discuss?<input required placeholder="e.g. Thesis consultation" value={bookForm.topic} onChange={(e) => setBookForm({ ...bookForm, topic: e.target.value })} /></label><label className="field-wide">Anything else? <span className="optional">optional</span><textarea rows={2} placeholder="Share a little context before your visit" value={bookForm.notes} onChange={(e) => setBookForm({ ...bookForm, notes: e.target.value })} /></label></div><div className="booking-footer"><span><Shield size={14} /> Your student details are only shared with faculty.</span><button className="primary-button" type="submit">Request appointment <ArrowRight size={15} /></button></div></form></Modal>}
    {rescheduleId && <Modal title="Reschedule appointment" eyebrow="PROPOSE A NEW TIME" onClose={() => setRescheduleId('')}><form className="professor-form reschedule-form" onSubmit={saveReschedule}><p className="modal-description">Choose a new slot. The student will see this as a reschedule request.</p><label>New date<input type="date" required min="2026-11-23" value={rescheduleDate} onChange={(e) => setRescheduleDate(e.target.value)} /></label><label>New time<select value={rescheduleTime} onChange={(e) => setRescheduleTime(e.target.value)}>{['7:00 AM', '8:00 AM', '9:00 AM', '10:00 AM', '11:00 AM', '12:00 PM', '1:00 PM', '2:00 PM', '3:00 PM', '4:00 PM'].map((time) => <option key={time}>{time}</option>)}</select></label><div className="booking-footer"><span><Shield size={14} /> Student confirmation is still needed.</span><button type="submit" className="primary-button">Send new time <ArrowRight size={15} /></button></div></form></Modal>}
    {profOpen && <Modal title="Add a professor" eyebrow="FACULTY ACCESS" onClose={() => setProfOpen(false)}><form className="professor-form" onSubmit={addProfessor}><p className="modal-description">Create a faculty profile and send an invitation to join CPSPA Connect.</p><label>Full name<input required placeholder="e.g. Dr. Juan Dela Cruz" value={profForm.name} onChange={(e) => setProfForm({ ...profForm, name: e.target.value })} /></label><label>University email<input required type="email" placeholder="name@pup.edu.ph" value={profForm.email} onChange={(e) => setProfForm({ ...profForm, email: e.target.value })} /></label><div className="form-grid"><label>Employee ID<input required placeholder="PUP-0000" value={profForm.id} onChange={(e) => setProfForm({ ...profForm, id: e.target.value })} /></label><label>Phone number<input required type="tel" placeholder="+63 9XX XXX XXXX" value={profForm.phone} onChange={(e) => setProfForm({ ...profForm, phone: e.target.value })} /></label></div><div className="booking-footer"><span><Shield size={14} /> Invitation access is for CPSPA faculty.</span><button type="submit" className="primary-button">Send invitation <ArrowRight size={15} /></button></div></form></Modal>}
    {toast && <div className="toast"><span><Check size={15} /></span>{toast}<button onClick={() => setToast('')} aria-label="Dismiss notification"><X size={15} /></button></div>}
    {mobileNav && <button className="mobile-scrim" onClick={() => setMobileNav(false)} aria-label="Close navigation" />}
  </div>
}







